import json, sys, html as _h

BOOK = {'title': 'It Plays at Midnight', 'author': 'Signature original', 'genre': 'Gothic Tales', 'chapters': [{'n': 1, 'title': 'Move-In', 'text': "Anna Petrova got the keys to the marsh village on a Tuesday, in fog so thick the house was a rumor until the door opened. It smelled of dust and old winters. It felt — Anna Petrova would later swear — like being watched by something patient.\n\nThe first night, Anna Petrova found a locked nursery. It wasn't in any box. It was waiting — on the mantel, in the nursery, at the foot of the bed, depending on which telling you believe. This telling says: the mantel.\n\nAnna Petrova told themselves it was the previous tenant's. Left behind. Nothing more. But at 3 a.m., a locked nursery did what a locked nursery does, and Anna Petrova sat up in the dark with their heart hammering the truth: this was no leftover."}, {'n': 2, 'title': 'Escalation', 'text': "Day three: a locked nursery moved on its own. Day four: the whispers started in the walls, spelling a name Anna Petrova almost recognized. Day five: his best friend Sam came for dinner and went white at the cold spot on the stairs.\n\nThe medium, Madame Zara, came at his best friend Sam's begging and left within the hour, pale. 'It isn't a ghost,' she said at the door. 'the drowned choir never died. That's the problem. It just waited.'\n\n'the drowned choir,' his best friend Sam whispered, though Anna Petrova hadn't said the name yet. Everyone in the county knew the story of the marsh village. Everyone pretended they didn't."}, {'n': 3, 'title': 'The Pattern', 'text': "The nursery door, locked for decades, opened for Anna Petrova like it had been waiting. Inside: dust, a small bed, and a locked nursery's twin — the other half of whatever had been broken that terrible night.\n\n'courage is a light,' Anna Petrova said to the dark, and the dark laughed. But it was a nervous laugh. Even the drowned choir could tell: this one wasn't going to run.\n\nAnna Petrova mapped it like a disease: every incident in the marsh village centered on a locked nursery, and every a locked nursery led back to the same date, the same room, the same name. the drowned choir wasn't haunting the house. the drowned choir was the house, wearing it like a coat."}, {'n': 4, 'title': 'The Night', 'text': 'It came on the anniversary, as Anna Petrova knew it would. The fog pressed against the windows of the marsh village like a face. a locked nursery activated — played, filled, showed, rang, drew, unlocked — and the drowned choir stepped out of the walls.\n\nhis best friend Sam arrived — of course his best friend Sam did, called by the thing friends are — with headlights and a crowbar and no plan at all. Together they forced the drowned choir back toward the nursery, toward a locked nursery, toward the broken place.\n\nAnna Petrova understood then what had to be done: not destroy a locked nursery, but complete it. Join the halves. Speak the name. Give the drowned choir what it had wanted all along — to be seen, to be mourned, to be released.'}, {'n': 5, 'title': 'Aftermath', 'text': "the marsh village is for sale again, and Anna Petrova is staying. Someone has to be here who knows. Someone has to keep the light on. That someone is Anna Petrova now.\n\nThe archives got a new entry, in Anna Petrova's handwriting: what happened, what worked, what it cost. Let the next tenant know. Let no one ever pretend again.\n\na locked nursery, mended, sits on the mantel. It doesn't play, or fill, or show. It's just an object now — which is to say, it's just a story. Anna Petrova keeps it to remember: courage is a light."}, {'n': 6, 'title': 'Epilogue: The Light Kept', 'text': "his best friend Sam visits every anniversary with pancakes and bad jokes. They don't talk about that night. They don't need to. It's in the walls — but the walls, now, are just walls.\n\nSometimes a locked nursery catches the light oddly, and Anna Petrova feels the old chill. Then Anna Petrova touches it, whole and quiet, and remembers the choice: to face it, to mend it, to stay.\n\nAnd the marsh village stands in its fog, ordinary and beloved, a house like any other — except that once, it was haunted, and once, someone stayed. That makes all the difference."}]}

def word_count():
    return sum(len(c["text"].split()) for c in BOOK["chapters"])

def print_book(ch=None):
    print("=" * 64)
    print(BOOK["title"].upper(), "\nby", BOOK["author"], "-", BOOK["genre"])
    print("=" * 64)
    for c in BOOK["chapters"]:
        if ch and c["n"] != ch:
            continue
        print("\n\nCHAPTER %d: %s\n%s" % (c["n"], c["title"], "-" * 40))
        print(c["text"])
    print("\n[%d words, %d chapters — complete]" % (word_count(), len(BOOK["chapters"])))

def search(word):
    w = word.lower()
    for c in BOOK["chapters"]:
        for i, para in enumerate(c["text"].split("\n\n")):
            if w in para.lower():
                print("[ch %d, para %d] %s..." % (c["n"], i + 1, para[:160].replace("\n", " ")))

def write_html(path="book.html"):
    parts = ["<html><head><meta charset='utf-8'><title>%s</title></head><body>" % _h.escape(BOOK["title"])]
    parts.append("<h1>%s</h1><p><i>by %s — %s</i></p>" % (_h.escape(BOOK["title"]), _h.escape(BOOK["author"]), _h.escape(BOOK["genre"])))
    for c in BOOK["chapters"]:
        parts.append("<h2>Chapter %d: %s</h2>" % (c["n"], _h.escape(c["title"])))
        for para in c["text"].split("\n\n"):
            parts.append("<p>%s</p>" % _h.escape(para))
    parts.append("</body></html>")
    open(path, "w").write("\n".join(parts))
    print("wrote", path)

if __name__ == "__main__":
    a = sys.argv[1:]
    if a and a[0] == "html":
        write_html()
    elif len(a) >= 2 and a[0] == "search":
        search(a[1])
    elif a and a[0].isdigit():
        print_book(int(a[0]))
    else:
        print_book()

